SELECT product_name AS productName, category AS category, SUM(quantity) AS totalQuantity, SUM(amount) AS totalAmount, COUNT(*) AS orderCount FROM biz_sales_order
order_date BETWEEN #{startDate} AND #{endDate}
AND category = #{category}
AND dept_id IN
#{deptId}
GROUP BY product_name, category ORDER BY totalAmount DESC

SELECT DATE_FORMAT(order_date, '%Y-%m') AS statMonth, SUM(quantity) AS totalQuantity, SUM(amount) AS totalAmount FROM biz_sales_order
order_date BETWEEN #{startDate} AND #{endDate}
AND category = #{category}
AND dept_id IN
#{deptId}
GROUP BY DATE_FORMAT(order_date, '%Y-%m') ORDER BY statMonth ASC
